def solve(grid):
    height = len(grid)
    if height == 0:
        return []
    width = len(grid[0])

    counts = {}
    for r in range(height):
        for c in range(width):
            val = grid[r][c]
            if val != 0:
                counts[val] = counts.get(val, 0) + 1

    sorted_items = sorted(counts.items(), key=lambda x: x[1])

    new_grid = [[0] * width for _ in range(height)]

    curr_row = height - 1
    for val, count in reversed(sorted_items):
        for c in range(width - count, width):
            new_grid[curr_row][c] = val
        curr_row -= 1

    return new_grid
